import{_ as l,l as r,o as e,c as s,v as t,p as n,x as o,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"倒塌抑制","description":"","frontmatter":{"title":"倒塌抑制","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/collapse-mitigation.md","filePath":"litho/collapse-mitigation.md","lastUpdated":1789023840000}'),c={name:"litho/collapse-mitigation.md"};function _(m,a,E,u,f,A){const i=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="倒塌抑制" tabindex="-1">倒塌抑制 <a class="header-anchor" href="#倒塌抑制" aria-label="Permalink to &quot;倒塌抑制&quot;">​</a></h1><div class="epigraph"><p>毛细力给定之后，还能改的是深宽比、模量、表面和干燥路径。抑制是力学预算，不是再加一次 OPC。</p><footer>—— 接续 [图形倒塌](/litho/pattern-collapse)；Mack / Levinson</footer></div><p><a href="/litho/rinse-surfactant">上一课</a>把液体张力接到干燥。缺口是工程对策清单：轨道上实际怎么压倒塌，而不把责任推回空中像。本课只列抑制手段与代价，不重写毛细压差公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>EUV / 高 NA 薄胶仍可能局部高深宽比（孔、密集线）。光学窗口合格、倒塌仍发生，良率记在随机缺陷或桥连里会分错类。需要一套<strong>显影后、刻蚀前</strong>的力学干预。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>手段分层。几何：降胶厚（三层把抗刻蚀交给 SOC）、放宽局部深宽比。材料：硬烤、UV 固化提高模量（后课）。液体：表面活性剂、溶剂置换、超临界干燥。表面：疏水化减少弯月面钉扎。每条都有缺陷或 CD 代价，必须进工艺窗口，不能只进一张 SEM 好图。</p>',7)),(e(),n(h,null,{default:o(()=>[p(i,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAP%5B%22%E6%AF%9B%E7%BB%86%E5%8A%9B%22%5D%20--%3E%20H%5B%22%E9%99%8D%20H%20%E6%88%96%E5%A2%9E%E6%A8%A1%E9%87%8F%22%5D%0A%20%20CAP%20--%3E%20G%5B%22%E9%99%8D%20%CE%B3%22%5D%0A%20%20CAP%20--%3E%20D%5B%22%E6%94%B9%E5%B9%B2%E7%87%A5%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">OPC 加粗根部可以抗倒，但那是成像课已经付过的 MEEF。轨道抑制不应假装能替代根部宽度。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>倒塌判据大致是毛细力矩对抗弯刚度。降 \\(H\\)、增 \\(E\\)、降 \\(\\gamma\\) 都进同一不等式。随机性课的 LER 让有效 \\(W\\) 更窄，倒塌阈值比光滑线更苛刻。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课去渣是等离子体或弱氧化，不是干燥力学。已倒塌的线去渣救不回来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>抑制 = 深宽比、模量、液体、干燥四条预算。</li><li>与 OPC 根部加粗分工，不互相冒充。</li><li>出处：pattern collapse 课；轨道对策通识。</li></ul>',7))])}const C=l(c,[["render",_]]);export{B as __pageData,C as default};
